INSERT INTO `locations` (`id`, `name`, `slug`, `city`, `emirate`, `description`, `is_featured`, `image_url`, `meta_title`, `meta_description`) VALUES
(1, 'Dubai Hills Estate', 'dubai-hills-estate', 'Dubai', 'Dubai', 'The green heart of Dubai, featuring an 18-hole championship golf course, Dubai Hills Mall, and luxury villas.', 1, '/assets/images/villa-dubai-hills.jpg', 'Properties for Sale in Dubai Hills Estate | DRL Dwarika Real Estate', 'Discover villas, townhouses and apartments for sale in Dubai Hills Estate with DRL Dwarika Real Estate LLC.'),
(2, 'Downtown Dubai', 'downtown-dubai', 'Dubai', 'Dubai', 'The centre of now, home to the Burj Khalifa, Dubai Mall, and premier luxury high-rise residences.', 1, '/assets/images/apartment-downtown.jpg', 'Luxury Downtown Dubai Properties | DRL Dwarika Real Estate', 'Browse exclusive high-rise apartments and luxury penthouses in Downtown Dubai with iconic Burj Khalifa views.'),
(3, 'Jumeirah Village Circle (JVC)', 'jumeirah-village-circle', 'Dubai', 'Dubai', 'A serene, high-yield residential community offering modern townhouses and family apartments.', 1, '/assets/images/townhouse-jvc.jpg', 'Properties in JVC Dubai | DRL Dwarika Real Estate LLC', 'Explore affordable luxury townhouses and high-ROI investment apartments in Jumeirah Village Circle.'),
(4, 'Palm Jumeirah', 'palm-jumeirah', 'Dubai', 'Dubai', 'World-renowned archipelago offering beachfront villas, ultra-luxury penthouses, and private marinas.', 1, '/assets/images/penthouse-palm.jpg', 'Palm Jumeirah Luxury Beachfront Properties | DRL Dwarika', 'World-class beachfront mansions and signature penthouses on the iconic Palm Jumeirah.'),
(5, 'Business Bay', 'business-bay', 'Dubai', 'Dubai', 'Dubai central business district along the Dubai Canal, featuring grade-A offices and luxury residential towers.', 1, '/assets/images/commercial-business-bay.jpg', 'Business Bay Properties & Commercial Real Estate | DRL Dwarika', 'Find premier corporate office spaces and high-yield residential canal towers in Business Bay.'),
(6, 'Dubai Creek Harbour', 'dubai-creek-harbour', 'Dubai', 'Dubai', 'Next-generation waterfront destination boasting panoramic wildlife sanctuary and skyline vistas.', 1, '/assets/images/offplan-creek.jpg', 'Off-Plan Properties in Dubai Creek Harbour | DRL Dwarika', 'Invest in off-plan waterfront apartments and investment projects at Dubai Creek Harbour.');
