INSERT INTO `agents` (`id`, `name`, `slug`, `designation`, `rera_brn`, `experience`, `photo_url`, `email`, `phone`, `whatsapp`, `short_bio`, `full_bio`, `languages`, `specializations`, `locations`, `testimonial_quote`, `testimonial_client`, `status`, `sort_order`) VALUES
(1, 'Omar Farooq', 'omar-farooq', 'Senior Luxury Property Consultant', '42918', '9+ Years Experience', '/assets/images/agents/omar-farooq.jpg', 'omar.farooq@dwarikarealestate.ae', '+971 50 234 5671', '971502345671', 'Specializing in prime villa communities across Dubai Hills Estate and luxury enclaves, Omar brings nearly a decade of high-end advisory experience to discerning home buyers and private investors.', 'Omar Farooq is a Senior Luxury Property Consultant at DRL Dwarika Real Estate LLC, licensed under Dubai Land Department (RERA BRN: 42918). Over nine years of distinguished service in Dubai\'s prime residential market, Omar has advised ultra-high-net-worth families, expatriate executives, and international institutional clients on acquiring trophy properties across master-planned developments.\n\nHis core advisory portfolio includes luxury standalone villas, golf course estates, and off-plan turnkey acquisitions in Dubai Hills Estate, Emirates Hills, and Downtown Dubai. Renowned for his analytical precision and transparent negotiation demeanor, Omar manages every transaction with uncompromising discretion and regulatory diligence.', '[\"English\", \"Arabic\", \"Urdu\"]', '[\"luxury\", \"residential\", \"off-plan\"]', '[\"Dubai Hills Estate\", \"Downtown Dubai\"]', 'Omar\'s deep understanding of Dubai Hills Estate was invaluable. He negotiated the best possible price for our family villa and navigated the DLD paperwork seamlessly.', 'Amit Sharma, Homeowner', 'active', 1),
(2, 'Elena Rostova', 'elena-rostova', 'Downtown & Waterfront Specialist', '51820', '7+ Years Experience', '/assets/images/agents/elena-rostova.jpg', 'elena.rostova@dwarikarealestate.ae', '+971 50 345 6782', '971503456782', 'Elena is an authority on luxury high-rise residences, serviced penthouses, and waterfront apartments in Downtown Dubai and Palm Jumeirah, serving international private wealth clients.', 'Elena Rostova joined DRL Dwarika Real Estate LLC with an established reputation across European and CIS investor networks. With over 7 years in the Dubai real estate ecosystem, Elena focuses exclusively on high-yielding Downtown Dubai apartments, luxury sky residences, and branded beachfront developments.\n\nShe holds extensive expertise in rental yield optimization, corporate tenant placement, and cross-border currency conveyancing under UAE banking frameworks. Fluent in English, Russian, and conversational French, Elena provides tailored concierge advisory for international buyers seeking safe-haven capital deployment and Golden Visa qualifying assets.', '[\"English\", \"Russian\", \"French\"]', '[\"luxury\", \"residential\", \"rental\"]', '[\"Downtown Dubai\", \"Palm Jumeirah\"]', 'Elena found our Downtown apartment within three days of our arrival in Dubai. Her insight into rental yield forecasts was spot on.', 'Sophie Laurent, Paris Investor', 'active', 2),
(3, 'Sarah Al-Mansoori', 'sarah-al-mansoori', 'Senior Residential Consultant', '49102', '6+ Years Experience', '/assets/images/agents/sarah-al-mansoori.jpg', 'sarah.almansoori@dwarikarealestate.ae', '+971 50 567 8904', '971505678904', 'Specializing in family-centric communities, modern townhouses, and high-yield suburban developments, Sarah delivers warm, dedicated guidance for first-time buyers and growing families.', 'Sarah Al-Mansoori is a certified Dubai real estate consultant specializing in master-planned communities including Jumeirah Village Circle (JVC), Dubai Hills Estate, and Arabian Ranches. With six years of client-centric practice, Sarah has helped hundreds of local and expatriate families secure their dream homes.\n\nHer thorough knowledge of community amenities, international school catchments, park networks, and service charges makes her the go-to advisor for end-user buyers. Sarah is renowned for her patience, transparent guidance on mortgage pre-approvals, and post-handover utility setups.', '[\"English\", \"Arabic\"]', '[\"residential\", \"rental\", \"off-plan\"]', '[\"Jumeirah Village Circle (JVC)\", \"Dubai Hills Estate\"]', 'Sarah helped our family navigate our first home purchase in JVC with genuine care. She made what felt daunting into a joyful experience.', 'Priya Nair, Homeowner', 'active', 3),
(4, 'Leila Hadid', 'leila-hadid', 'Ultra-Luxury & Penthouse Specialist', '47812', '8+ Years Experience', '/assets/images/agents/leila-hadid.jpg', 'leila.hadid@dwarikarealestate.ae', '+971 50 789 0126', '971507890126', 'Representing elite architectural masterpieces, beachfront estates on Palm Jumeirah, and bespoke sky penthouses, Leila offers private clients unparalleled access to off-market luxury listings.', 'Leila Hadid is one of Dubai\'s most respected luxury residential advisors, specializing in ultra-prime beachfront properties on Palm Jumeirah, waterfront mansions, and crown penthouses. Leila operates at the pinnacle of the Dubai luxury market, representing international ultra-high-net-worth clients, celebrity buyers, and royal family offices.\n\nKnown for her impeccable taste, discretion, and access to private pocket listings never advertised publicly, Leila provides white-glove advisory from initial confidential consultation through to title deed escrow settlement.', '[\"English\", \"Arabic\", \"French\"]', '[\"luxury\", \"residential\", \"off-plan\"]', '[\"Palm Jumeirah\", \"Dubai Creek Harbour\"]', 'Leila\'s access to off-market Palm Jumeirah residences was unmatched. She handled our transaction with the highest level of confidentiality.', 'Tariq Mansoor, Private Investor', 'active', 4),
(5, 'Marcus Vance', 'marcus-vance', 'Commercial Real Estate Director', '36219', '14+ Years Experience', '/assets/images/agents/marcus-vance.jpg', 'marcus.vance@dwarikarealestate.ae', '+971 50 678 9015', '971506789015', 'With 14 years of commercial brokerage experience in the UK and UAE, Marcus advises multinational corporations, tech firms, and private funds on Grade-A office acquisitions and commercial leases.', 'Marcus Vance leads the Commercial Brokerage division at DRL Dwarika Real Estate LLC. Prior to joining the Dubai market eight years ago, Marcus advised FTSE 100 corporations on office relocations across London\'s financial district. In Dubai, he has transacted over 350,000 square feet of prime commercial real estate in Business Bay, DIFC, and Downtown Dubai.\n\nHis expertise encompasses commercial lease negotiations, corporate fit-out feasibility, freezone versus mainland licensing considerations, and sale-and-leaseback transactions for institutional property holders.', '[\"English\"]', '[\"commercial\", \"investment\", \"luxury\"]', '[\"Business Bay\", \"Downtown Dubai\"]', 'Marcus negotiated our corporate headquarters lease in Business Bay with total professionalism. We secured excellent terms and saved weeks of administrative delay.', 'David K., Regional Managing Director', 'active', 5),
(6, 'Rahul Kapoor', 'rahul-kapoor', 'Off-Plan & Investment Advisory Director', '38945', '11+ Years Experience', '/assets/images/agents/rahul-kapoor.jpg', 'rahul.kapoor@dwarikarealestate.ae', '+971 50 456 7893', '971504567893', 'A veteran real estate financial analyst and off-plan strategist, Rahul guides global portfolio investors in securing early-stage launch allocations with optimal capital appreciation trajectories.', 'Rahul Kapoor brings over eleven years of structured investment experience across Dubai\'s capital markets and top-tier master developers including Emaar, Nakheel, and Meraas. At DRL Dwarika Real Estate LLC, Rahul spearheads off-plan portfolio advisory, developer allotment negotiations, and ROI modeling for high-net-worth individuals and family offices.\n\nHis analytical approach breaks down construction milestones, escrow account protections, secondary market liquidity cycles, and tax-efficient UAE structuring. Rahul is a frequent market commentator and trusted advisor to investors seeking 8-12% target annualized returns.', '[\"English\", \"Hindi\", \"Urdu\"]', '[\"off-plan\", \"commercial\", \"residential\"]', '[\"Dubai Creek Harbour\", \"Business Bay\", \"Downtown Dubai\"]', 'Rahul\'s investment models for Dubai Creek Harbour gave us total confidence. His pre-launch access saved us significant capital.', 'Rajesh Patel, TechCorp India', 'active', 6);
INSERT INTO `founders` (`id`, `name`, `slug`, `designation`, `photo_url`, `short_bio`, `full_bio`, `background`, `leadership_areas`, `quote`, `email`, `phone`, `status`, `missing_fields`, `sort_order`) VALUES
(1, 'Founder & Managing Director [Draft Profile]', 'founder-managing-director', 'Founder & Managing Director', '', 'Executive leadership profile awaiting administrator verification. Oversees strategic institutional vision and corporate governance for DRL Dwarika Real Estate LLC.', 'DRL Dwarika Real Estate LLC was founded under a steadfast commitment to market transparency, professional governance, and sustainable investor prosperity in the UAE.\n\nUnder this leadership, the brokerage has cemented strategic alliances with Dubai\'s premier master developers and built an exceptional multilingual advisory desk headquartered in Business Bay.\n\n*Note for Administrator: Official biographical profile, portrait photography, and verified academic credentials to be updated via Admin Panel.*', 'Real Estate Brokerage Leadership, Institutional Capital Markets, Dubai Land Department Regulatory Frameworks', 'Strategic Vision, Institutional Alliances, Corporate Governance, Market Expansion', 'Opening doors to prosperity through uncompromising transparency, ethical counsel, and enduring value creation for our clients.', 'leadership@dwarikarealestate.ae', '+971 542202920', 'draft', 'Full Legal Name, Official Executive Portrait, Verified Qualifications', 1),
(2, 'Co-Founder & Chief Operating Officer [Draft Profile]', 'co-founder-coo', 'Co-Founder & Chief Operating Officer', '', 'Operational leadership profile awaiting administrator verification. Directs brokerage operations, developer relations, and transaction excellence.', 'Guiding operational execution and transaction integrity at DRL Dwarika Real Estate LLC, overseeing end-to-end conveyance, customer experience, and digital property intelligence systems.\n\nEnsures that every buyer, tenant, and institutional investor receives seamless regulatory protection, transparent escrow coordination, and prompt advisory service.\n\n*Note for Administrator: Official biographical profile, portrait photography, and verified academic credentials to be updated via Admin Panel.*', 'Real Estate Operations, Developer Portfolios, Escrow & Conveyance Governance, Client Experience', 'Brokerage Operations, Developer Alliances, CRM Systems, RERA Regulatory Compliance', 'Excellence in real estate is built upon trust, operational rigor, and relentless dedication to our investors.', 'operations@dwarikarealestate.ae', '+971 542202920', 'draft', 'Full Legal Name, Official Executive Portrait, Verified Qualifications', 2);
