INSERT INTO `services` (`id`, `title`, `slug`, `short_desc`, `full_desc`, `icon`, `benefits`, `process`, `sort_order`, `is_active`, `meta_title`, `meta_description`) VALUES
(1, 'Buy Home', 'buy-property', 'Find your perfect dream residence across Dubai’s most coveted freehold master communities.', 'Whether you are purchasing your primary family home or a blue-chip vacation property, our seasoned advisors guide you through inventory selection, developer credentials, title deed verification, and escrow account procedures. We provide transparent access to off-market listings, pre-launch allotments, and ready resale transactions.', 'fa-house', '[\"Access to exclusive pre-launch developments\", \"Full RERA and DLD regulatory verification\", \"Negotiation for optimal pricing & payment plans\", \"End-to-end conveyance & title deed handover\"]', '[\"Personalized Lifestyle Discovery Session\", \"Curated Property Portfolio Shortlisting\", \"Private On-Site VIP Viewings\", \"Offer Formulation & MOU Contract Drafting\", \"DLD Registration & Key Handover\"]', 1, 1, 'Buy Property in Dubai | Luxury Villas & Apartments | DRL Dwarika', 'Explore premier properties for sale in Dubai. Trust DRL Dwarika Real Estate LLC for verified listings, legal conveyance and seamless home buying.'),
(2, 'Sell Property', 'sell-property', 'Maximize your asset value with tailored global marketing campaigns and qualified high-net-worth buyers.', 'Selling luxury real estate in Dubai demands strategic positioning, premium architectural photography, and international buyer reach. Dwarika Real Estate LLC deploys precision digital syndication, targeted private wealth matching, and strict price protection to close transactions swiftly at premium market multiples.', 'fa-hand-holding-dollar', '[\"Accurate professional comparative market analysis (CMA)\", \"High-resolution staging, 4K video & Matterport 3D tours\", \"Direct access to pre-qualified global investors\", \"Dedicated transaction coordinator from listing to closing\"]', '[\"Property Valuation & Market Positioning\", \"Media Production & Architectural Staging\", \"Global Multi-Channel Syndication\", \"Qualified Buyer Screening & Viewings\", \"Sales Agreement Execution & Escrow Settlement\"]', 2, 1, 'Sell Your Property in Dubai | Highest Valuation | DRL Dwarika', 'Sell your Dubai apartment, villa or commercial property at the highest valuation with DRL Dwarika Real Estate LLC.'),
(3, 'Consultancy', 'property-consultancy', 'Expert real estate advisory to guide individuals and enterprises on market regulations, valuations, and structuring.', 'The UAE real estate market evolves rapidly with new laws, Golden Visa regulations, and tax policies. Our experienced property consultants provide impartial, data-driven counsel on ownership structures, freehold zones, corporate acquisitions, leasehold conversions, and mortgage structuring.', 'fa-user-tie', '[\"Impartial market intelligence and trend forecasting\", \"Golden Visa (10-Year) real estate qualification guidance\", \"Mortgage pre-approval & financing assistance\", \"Commercial and residential lease advisory\"]', '[\"Initial Client Advisory Call\", \"Regulatory & Financial Feasibility Analysis\", \"Strategic Roadmap Formulation\", \"Execution Support & Legal Documentation\"]', 3, 1, 'Real Estate Consultancy Dubai | DRL Dwarika Real Estate LLC', 'Strategic property advisory and consultancy services for home buyers and institutional investors in Dubai.'),
(4, 'Investment Advisory', 'investment-advisory', 'High-yield portfolio structuring, rental yield optimization, and Golden Visa capital allocation strategies.', 'We help international investors and wealth managers build resilient property portfolios in Dubai generating 7% to 10% net yields. We analyze rental demand heatmaps, off-plan capital appreciation trajectories, short-term holiday home projections, and exit strategies across market cycles.', 'fa-chart-line', '[\"Targeted net rental yield optimization (7% - 10%+)\", \"Off-plan early stage capital appreciation entry points\", \"Golden Visa compliant asset aggregation\", \"Full turnkey post-handover property asset management\"]', '[\"Investor Capital & ROI Target Assessment\", \"Algorithmic Yield & Growth Modeling\", \"Asset Selection & Allocation\", \"Acquisition & Tenant Placement Support\"]', 4, 1, 'Real Estate Investment Advisory Dubai | High Yields | DRL Dwarika', 'Maximize returns on Dubai real estate with DRL Dwarika Real Estate LLC investment advisory and portfolio management.');
INSERT INTO `testimonials` (`id`, `client_name`, `client_title`, `location`, `quote`, `avatar_initial`, `rating`, `is_featured`, `sort_order`) VALUES
(1, 'Amit Sharma', 'Homeowner', 'Dubai', 'Dwarika Real Estate made our home buying process so easy. Their team was professional, responsive and genuinely helpful.', 'A', 5, 1, 1),
(2, 'Priya Nair', 'Property Investor', 'Abu Dhabi', 'Excellent service and great property options. Highly recommended for anyone looking to invest in Dubai.', 'P', 5, 1, 2),
(3, 'Rahul Verma', 'Business Owner', 'Sharjah', 'From property search to final paperwork, everything was handled smoothly. Truly a reliable real estate partner.', 'R', 5, 1, 3);
INSERT INTO `enquiries` (`id`, `property_id`, `service_id`, `name`, `email`, `phone`, `subject`, `message`, `status`) VALUES
(1, 1, 1, 'Farhan Al Qasimi', 'farhan.qasimi@emirates.ae', '+971 52 984 1120', 'Inquiry on Modern Villa in Dubai Hills', 'Hello, I am interested in scheduling a viewing for the 4-bedroom Modern Villa in Dubai Hills Estate this Saturday afternoon. Please let me know the availability.', 'new'),
(2, 2, NULL, 'Sophie Laurent', 'sophie.laurent@outlook.com', '+33 6 42 19 88 02', 'Downtown Luxury Apartment Inquiry', 'I am an investor based in Paris looking for ready 2-bed apartments in Downtown Dubai for high rental yields. Is this unit currently rented or vacant on transfer?', 'contacted'),
(3, NULL, 4, 'Rajesh Patel', 'rajesh.patel@techcorp.in', '+91 98200 44551', 'Golden Visa Investment Strategy', 'Looking to invest AED 3M to qualify for the 10-Year UAE Golden Visa. Please share your recommended off-plan and ready options with favorable payment terms.', 'qualified');
